                return href == null ? null : href.trim();
            }
            return null;
        }
        return null;
    }

    private String attributeValue(Matcher matcher) {
        for (int i = 1; i <= matcher.groupCount(); i++) {
            if (matcher.group(i) != null) {
                return matcher.group(i);
            }
        }
